import '../model/document_dataset.dart';
import '../progress/cancellation_token.dart';
import '../progress/document_progress.dart';
import 'report_definition.dart';

/// Contract implemented by report renderers (PDF, Excel, HTML, CSV).
abstract interface class ReportRenderer {
  /// Format identifier of the renderer (e.g. 'pdf', 'xlsx', 'html').
  String get formatId;

  /// Primary file extension generated by this renderer.
  String get primaryExtension;

  /// Renders [definition] with data from [dataset] into raw document bytes.
  Future<List<int>> render(
    ReportDefinition definition,
    DocumentDataset dataset, {
    CancellationToken? cancellationToken,
    DocumentProgressCallback? onProgress,
  });
}
